            padding: 12px;
            width: 320px;
            max-height: 280px;
            overflow-y: auto;
            z-index: 10;
            display: none;
        }

        .emoji-panel.show {
            display: block;
        }

        .emoji-grid {
            display: grid;
            grid-template-columns: repeat(6, 1fr);
            gap: 6px;
        }

        .emoji-btn {
            padding: 8px;
            border: none;
            background: transparent;
            cursor: pointer;
            border-radius: 6px;
            transition: background 0.2s;
            display: flex;
            align-items: center;
            justify-content: center;
            aspect-ratio: 1;
        }

        .emoji-btn:hover {
            background: #f0f0f0;
        }

        .emoji-btn img {
            width: 24px;
            height: 24px;
        }

        .modal-footer {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .char-count {
            font-size: 13px;
            color: #999;
        }

        .char-count.over {
            color: #ff4d4f;
        }

        .submit-btn {
            background: #07c160;
            color: #fff;
            border: none;
            padding: 8px 24px;
            border-radius: 20px;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
        }

        .submit-btn:disabled {
            background: #ccc;
            cursor: not-allowed;
        }

        /* 图片预览 */
        .image-preview {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.9);
            z-index: 300;
            display: none;
            align-items: center;
            justify-content: center;
        }

        .image-preview.show {
            display: flex;
        }

        .image-preview img {
            max-width: 90%;
            max-height: 90%;
            border-radius: 8px;
        }

        .image-preview-close {
            position: absolute;
            top: 20px;
            right: 20px;
            font-size: 32px;
            color: #fff;
            cursor: pointer;
        }

        /* Toast */
        .toast {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0, 0, 0, 0.75);
            color: #fff;
            padding: 12px 24px;
            border-radius: 8px;
            font-size: 14px;
            z-index: 400;
            display: none;
        }

        .toast.show {
            display: block;
        }

        /* 隐藏 */
        .hidden {
            display: none !important;
        }

        /* 深色模式 */
        html.dark, body.dark {
            background: #1a1a1a;
            color: #e0e0e0;
        }

        /* 确保在深色模式下整个页面都是深色背景 */
        .dark {
            background: #1a1a1a;
        }

        .dark .header {
            background: #2d2d2d;
            border-bottom-color: #3d3d3d;
        }

