        .dark .comment-list {
            background: #2d2d2d;
        }

        .dark .comment-item {
            border-bottom-color: #3d3d3d;
        }

        .dark .comment-username {
            color: #e0e0e0;
        }

        .dark .comment-content {
            color: #ccc;
        }

        .dark .comment-time {
